export default function install(app){const changed=new Map();let active=true;const root=app.view.ui.container;function lines(){const result=[];for(const panel of root.querySelectorAll('section[data-title]')){const overlay=panel.parentElement;if(!overlay||overlay.style.pointerEvents!=='none')continue;for(const svg of overlay.children){if(svg.tagName?.toLowerCase()!=='svg'||svg.getAttribute('aria-hidden')!=='true')continue;for(const line of svg.querySelectorAll('line'))result.push(line);}}return [...new Set(result)];}function apply(){if(!active)return;for(const line of lines()){if(changed.has(line))continue;changed.set(line,{width:line.getAttribute('stroke-width'),cap:line.getAttribute('stroke-linecap'),filter:line.style.filter});line.setAttribute('stroke-width','3');line.setAttribute('stroke-linecap','round');line.style.filter='drop-shadow(0px 1px 2px rgba(0,0,0,.5))';}}const observer=new MutationObserver(apply);observer.observe(root,{childList:true,subtree:true});apply();app.actions.register('esg-connector-width-state',()=>({lineCount:lines().length,widths:[...new Set(lines().map(l=>l.getAttribute('stroke-width')))],tracked:changed.size}));app.onCleanup(()=>{active=false;observer.disconnect();for(const [line,old] of changed){if(old.width===null)line.removeAttribute('stroke-width');else line.setAttribute('stroke-width',old.width);if(old.cap===null)line.removeAttribute('stroke-linecap');else line.setAttribute('stroke-linecap',old.cap);line.style.filter=old.filter;}changed.clear();});}